      en: "A traditional oasis fortress town in the Saoura valley, located deep in the Sahara and with a rich caravan history.",
      es: "Una ciudad-fortaleza tradicional de oasis en el valle del Saoura, situada en lo profundo del Sáhara y con una rica historia de caravanas.",
      pt: "Uma cidade-fortaleza tradicional de oásis no vale do Saoura, situada no coração do Saara e com uma rica história de caravanas.",
      fr: "Une ville-forteresse traditionnelle d'oasis dans la vallée de la Saoura, située au cœur du Sahara et riche d'une longue histoire caravanière.",
