      pt: "As antigas ruínas do porto romano perto da atual Bethioua, que tiveram uma importância estratégica para a exportação agrícola na antiguidade.",
      fr: "Les anciennes ruines du port romain près de l'actuelle Bethioua, qui revêtaient une importance stratégique pour l'exportation agricole dans l'Antiquité.",
